import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';

const ProblemDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { token } = useAuth();
  const [problem, setProblem] = useState(null);
  const [code, setCode] = useState('');
  const [language, setLanguage] = useState('java');
  const [output, setOutput] = useState('');
  const [error, setError] = useState('');
  const [submissionResult, setSubmissionResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [customInput, setCustomInput] = useState('');
  const [running, setRunning] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const templates = {
    java: `import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Write your code here
        
    }
}`,
    cpp: `#include <bits/stdc++.h>
using namespace std;

int main() {
    // Write your code here
    
    return 0;
}`
  };

  useEffect(() => {
    fetchProblem();
    setCode(templates[language]);
  }, [id, language]);

  const fetchProblem = async () => {
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/problems/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblem(response.data.problem);
    } catch (error) {
      console.error('Error fetching problem:', error);
      navigate('/problems');
    }
  };

  const handleRun = async () => {
    setRunning(true);
    setOutput('');
    setError('');
    setSubmissionResult(null);

    try {
      const response = await axios.post(`${process.env.REACT_APP_API_URL}/submissions/run`, {
        problemId: id,
        code,
        language,
        input: customInput || problem?.sampleInput
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.error) {
        setError(response.data.error);
      } else {
        setOutput(response.data.output || '✅ Program executed successfully (no output)');
      }
    } catch (error) {
      setError(error.response?.data?.message || 'Error running code');
    } finally {
      setRunning(false);
    }
  };

  const handleSubmit = async () => {
    setSubmitting(true);
    setOutput('');
    setError('');
    setSubmissionResult(null);

    try {
      const response = await axios.post(`${process.env.REACT_APP_API_URL}/submissions/submit`, {
        problemId: id,
        code,
        language
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      setSubmissionResult(response.data);
      
      if (response.data.status === 'accepted') {
        setOutput('✅ All test cases passed! Great job! 🎉');
      } else {
        setOutput(`❌ ${response.data.passedTestCases}/${response.data.totalTestCases} test cases passed`);
      }
    } catch (error) {
      setError(error.response?.data?.message || 'Error submitting code');
    } finally {
      setSubmitting(false);
    }
  };

  if (!problem) {
    return (
      <div style={styles.loadingContainer}>
        <div className="loading-spinner"></div>
        <p>Loading problem...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* Navigation */}
      <nav style={styles.nav}>
        <div style={styles.navLeft}>
          <h1 style={styles.logo}>⚡ CodeArena</h1>
          <span style={styles.navSubtitle}>Problem</span>
        </div>
        <div style={styles.navRight}>
          <button onClick={() => navigate('/problems')} style={styles.navButton}>
            📚 Problems
          </button>
          <button onClick={() => navigate('/')} style={styles.navButton}>
            🏠 Dashboard
          </button>
        </div>
      </nav>

      {/* Problem Info */}
      <div style={styles.problemSection}>
        <div style={styles.problemHeader}>
          <div>
            <h1 style={styles.problemTitle}>{problem.title}</h1>
            <div style={styles.problemMeta}>
              <span style={{
                ...styles.difficultyBadge,
                backgroundColor: problem.difficulty === 'Easy' ? '#28a745' :
                               problem.difficulty === 'Medium' ? '#ffc107' : '#dc3545'
              }}>
                {problem.difficulty || 'Easy'}
              </span>
              <span style={styles.problemDate}>
                📅 Added: {new Date(problem.createdAt).toLocaleDateString()}
              </span>
            </div>
          </div>
        </div>

        <div style={styles.problemContent}>
          <div style={styles.descriptionSection}>
            <h3>📖 Description</h3>
            <p style={styles.description}>{problem.description}</p>

            <div style={styles.sampleSection}>
              <h4>Sample Input:</h4>
              <pre style={styles.sampleCode}>{problem.sampleInput}</pre>
              <h4>Sample Output:</h4>
              <pre style={styles.sampleCode}>{problem.sampleOutput}</pre>
            </div>

            <div style={styles.constraintsSection}>
              <h4>Constraints:</h4>
              <p style={styles.constraints}>{problem.constraints}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Code Editor */}
      <div style={styles.editorSection}>
        <div style={styles.editorControls}>
          <div style={styles.controlGroup}>
            <label style={styles.controlLabel}>Language:</label>
            <select
              value={language}
              onChange={(e) => {
                setLanguage(e.target.value);
                setCode(templates[e.target.value]);
              }}
              style={styles.select}
            >
              <option value="java">☕ Java</option>
              <option value="cpp">⚡ C++</option>
            </select>
          </div>
          <div style={styles.actionButtons}>
            <button
              onClick={handleRun}
              disabled={running || submitting}
              style={styles.runButton}
            >
              {running ? '⏳ Running...' : '▶ Run'}
            </button>
            <button
              onClick={handleSubmit}
              disabled={running || submitting}
              style={styles.submitButton}
            >
              {submitting ? '⏳ Submitting...' : '📤 Submit'}
            </button>
          </div>
        </div>

        <textarea
          value={code}
          onChange={(e) => setCode(e.target.value)}
          style={styles.editor}
          spellCheck={false}
        />

        <div style={styles.inputOutputSection}>
          <div style={styles.inputGroup}>
            <h4>📝 Custom Input (Optional):</h4>
            <textarea
              value={customInput}
              onChange={(e) => setCustomInput(e.target.value)}
              style={styles.customInput}
              placeholder="Enter custom input here..."
              rows={3}
            />
          </div>
          <div style={styles.outputGroup}>
            <h4>📤 Output:</h4>
            <div style={styles.outputBox}>
              {error ? (
                <pre style={styles.errorOutput}>{error}</pre>
              ) : (
                <pre style={styles.successOutput}>{output || 'Run your code to see output'}</pre>
              )}
            </div>
          </div>
        </div>

        {/* Submission Results */}
        {submissionResult && (
          <div style={styles.resultSection}>
            <h3>📊 Submission Results</h3>
            <div style={{
              ...styles.resultSummary,
              ...(submissionResult.status === 'accepted' ? styles.resultAccepted : styles.resultFailed)
            }}>
              <div style={styles.resultScore}>
                Score: <strong>{submissionResult.score.toFixed(1)}%</strong>
              </div>
              <div>
                {submissionResult.passedTestCases} / {submissionResult.totalTestCases} Test Cases Passed
              </div>
              <div style={styles.resultStatus}>
                Status: {submissionResult.status === 'accepted' ? '✅ Accepted' : '❌ Wrong Answer'}
              </div>
            </div>

            <div style={styles.testCasesDetails}>
              <h4>Test Case Details:</h4>
              {submissionResult.results.map((result, index) => (
                <div key={index} style={{
                  ...styles.testCaseItem,
                  ...(result.passed ? styles.testCasePassed : styles.testCaseFailed)
                }}>
                  <div style={styles.testCaseHeader}>
                    <span>Test Case {index + 1}</span>
                    <span>{result.passed ? '✅ Passed' : '❌ Failed'}</span>
                  </div>
                  {!result.passed && (
                    <div style={styles.testCaseDetails}>
                      <div>Expected: <pre>{result.expected}</pre></div>
                      <div>Got: <pre>{result.output || 'No output'}</pre></div>
                      {result.error && <div>Error: <pre style={styles.testError}>{result.error}</pre></div>}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

